/**
 * Scoped to this atom's own contract per testing.md: given href/no href, does it render the
 * right element type; does aria-checked/tabIndex track isSelected/isFocusable; does the passed
 * imageUrl reach the DOM as the swatch's background-image fill; and — the regression guard —
 * does the swatch box's background-colour stay pinned to the recipe's own token declaration
 * regardless of the colour `name`, rather than picking up a raw CSS-colour-keyword the way base
 * SFCC's own `renderDefaultVariationAttribute` does (`backgroundColor={name.toLowerCase()}`) —
 * see index.tsx's own comment for the three reasons this atom deliberately does not replicate
 * that.
 *
 * Every render needs three wrappers, not just the router:
 *   - `ChakraProvider theme={theme}` (the real theme, not Chakra's default) — without it,
 *     `useMultiStyleConfig('ZimmColourSwatch', ...)` resolves against a theme with no such key
 *     registered and silently returns `{}` for both parts, which would make every assertion below
 *     pass vacuously against an unstyled node rather than against this recipe. Same reasoning as
 *     zimmProductMeta/index.test.tsx's own "resolves its recipe under a ChakraProvider" test.
 *   - `MemoryRouter` — this atom can render a react-router `Link`, which throws outside one.
 *   - `ZimmTokensGlobal` — without a `:root` definition for the `--zimm-*` variables the recipe
 *     references, a resolved-value assertion has nothing to distinguish "correct" from
 *     "regressed" (see the regression-guard test below).
 *
 * `getComputedStyle`, not `element.style`: Chakra resolves `__css` through Emotion, which applies
 * a generated class rather than an inline `style` attribute, so the inline `style` property never
 * reflects the resolved value — matching how every other Chakra-styles assertion in this codebase
 * reads a resolved value (zimmProductMeta/index.test.tsx, zimmProductPrice/index.test.tsx,
 * theme/index.test.tsx).
 *
 * One further, load-bearing wrinkle specific to a `var(--zimm-*)`-driven recipe (as opposed to a
 * bare Chakra-scale key, which those other files' assertions read): confirmed directly against
 * this file, jsdom's `getComputedStyle` does not substitute a custom property's value — it
 * echoes back the literal declaration text (`"var(--zimm-color-bg-02)"`), never the
 * resolved hex/rgb. That is actually what makes the regression guard below simple rather than
 * impossible: it asserts on that literal, unsubstituted declaration string, which is exactly
 * "which value authored this" — variable reference vs. some other literal. A real browser (Chrome
 * driving the Storybook `play` in index.stories.tsx) does perform the substitution; this file
 * doesn't need it to, because the literal declaration is the more direct thing to assert on.
 *
 * No ZimmIcon anywhere in this component, so no need for the ZimmIcon-throws-under-Vitest mock
 * documented in testing.md.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
import { ZimmColourSwatch } from './index';

const IMAGE_URL = 'https://picsum.photos/seed/zimmermann-bay-blue/400/600';

const renderSwatch = (overrides: Partial<React.ComponentProps<typeof ZimmColourSwatch>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <ZimmTokensGlobal />
        <ZimmColourSwatch name="Bay Blue" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} {...overrides} />
      </MemoryRouter>
    </ChakraProvider>,
  );

describe('ZimmColourSwatch', () => {
  test('renders an anchor carrying the given href when href is present', () => {
    renderSwatch({ href: '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL' });
    const swatch = screen.getByRole('radio');
    expect(swatch.tagName).toBe('A');
    expect(swatch).toHaveAttribute('href', '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL');
  });

  test('renders a non-anchor element when href is absent', () => {
    renderSwatch({ href: undefined });
    const swatch = screen.getByRole('radio');
    expect(swatch.tagName).not.toBe('A');
  });

  test('isSelected=true sets aria-checked="true"', () => {
    renderSwatch({ isSelected: true });
    expect(screen.getByRole('radio')).toHaveAttribute('aria-checked', 'true');
  });

  test('isSelected=false sets aria-checked="false"', () => {
    renderSwatch({ isSelected: false });
    expect(screen.getByRole('radio')).toHaveAttribute('aria-checked', 'false');
  });

  test('isFocusable=true sets tabIndex to 0', () => {
    renderSwatch({ isFocusable: true });
    expect(screen.getByRole('radio')).toHaveAttribute('tabindex', '0');
  });

  test('isFocusable=false sets tabIndex to -1', () => {
    renderSwatch({ isFocusable: false });
    expect(screen.getByRole('radio')).toHaveAttribute('tabindex', '-1');
  });

  test('renders the passed imageUrl as the swatch fill background-image', () => {
    renderSwatch({ imageUrl: IMAGE_URL });
    const swatch = screen.getByRole('radio');
    const imageEl = swatch.firstElementChild as HTMLElement;
    expect(getComputedStyle(imageEl).backgroundImage).toContain(IMAGE_URL);
  });

  test('does not set a raw CSS-colour-keyword backgroundColor from the colour name (regression guard)', () => {
    renderSwatch({ name: 'Bay Blue' });
    const swatch = screen.getByRole('radio');
    // The recipe's own unconditional declaration — see the file-level comment above for why this
    // literal, unsubstituted form is what jsdom actually reports. A regression re-adding
    // `backgroundColor={name.toLowerCase()}` as an extra prop on this element would overwrite this
    // key in the final merged style object (Chakra assigns component style props after `__css`),
    // so this would read the literal "bay blue" instead — proven by an actual mutation run, not
    // assumed; see the PR body / step report for that run's before/after output.
    expect(getComputedStyle(swatch).backgroundColor).toBe('var(--zimm-color-bg-02)');
  });
});

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for a single PDP colour swatch — a clickable rectangle filled with that colour
 * variation's product photo. Two parts: `swatch` is the outer clickable box (geometry,
 * background, border, focus ring); `image` is the element carrying the dynamic
 * background-image fill — the URL itself cannot live here, see the component's own comment on
 * why that one `__css` spread stays dynamic.
 *
 * Values below are read directly off Figma for the three states this recipe distinguishes, not
 * estimated from surrounding metadata — Unselected (node 40000307:13826), Selected
 * (40000307:13831), Focus (40002689:3839), all under `size=Large/Rectangle`.
 */
export const ZimmColourSwatch = {
  parts: ['swatch', 'image'],

  baseStyle: ({ selected }: { selected?: boolean }): Record<string, SystemStyleObject> => ({
    swatch: {
      display: 'inline-block',
      cursor: 'pointer',
      // Figma's Rectangle width (48px). Height (72px) has no direct token — the named scale has
      // nothing between 64px and 140px — so it's expressed as an aspect ratio on the width
      // instead. 2:3, not the incidentally different ratio Figma's raw code-gen attached to the
      // placeholder product photo pasted into that frame instance: the Selected-state node
      // carries its own dev annotation reading "Image aspect ratio - 2:3", which is the number
      // to trust here.
      width: 'var(--zimm-scale-1200)',
      aspectRatio: '2 / 3',
      // Identical across Unselected/Selected/Focus — ivory[200] / background['02'] in
      // theme/foundation/colour.ts.
      backgroundColor: 'var(--zimm-color-bg-02)',
      // Selected: a bottom-only border — the raw Figma export is unambiguous, a `border-b`
      // utility rather than a full box border. Colour is grey[900] / border.focus, the only
      // alias-tier value that resolves to it (border.default and border.secondary are both
      // light greys and never appear anywhere in this design).
      ...(selected
        ? {
            borderBottomWidth: 'var(--zimm-border-width-default)',
            borderBottomStyle: 'solid',
            borderBottomColor: 'var(--zimm-color-border-focus)',
          }
        : {}),
      // Focus: Figma draws this as the Selected baseline plus a ring at slightly asymmetric
      // per-side offsets, same colour. Not replicated literally — there is no other precedent
      // anywhere in this codebase for a non-uniform ring, and the asymmetry reads as that one
      // frame instance's export noise rather than a deliberate design decision. Mirrors
      // zimmNavItem.css.ts's own focus-ring block instead: a uniform `outline` + `outlineOffset`
      // pair, applied independently of `selected` above — a swatch can be focused without being
      // selected, and selected without being focused. `--zimm-focus-ring` already composites the
      // same border-width/colour pair used above; `--zimm-focus-ring-offset-default` matches
      // three of Figma's four side offsets.
      //
      // `position: relative` + `zIndex: 1`, scoped to this focus-visible state only: the parent
      // `swatches` row (zimmColourSwatchGroup.css.ts) is `gap: 0`, so adjacent swatches sit
      // flush. `outlineOffset` is positive, so the ring paints *outside* this swatch's own
      // border box — and with zero gap, that outward ring overlaps the very next swatch's own
      // box. Both swatches are plain in-flow flex items (`position: static`, `z-index: auto`),
      // so painting follows tree order: the later sibling paints its opaque background on top
      // of the earlier swatch's ring wherever the two overlap, hiding exactly the shared
      // (right-hand) edge — confirmed in a real Chromium render, before this fix, via
      // `getBoundingClientRect`/`elementFromPoint` and a screenshot: the right edge and the
      // right-hand slivers of the top/bottom edges were missing for every swatch with a
      // right-hand sibling, while the last swatch in a row (nothing to its right) rendered a
      // complete rectangle. `zIndex` lifts this swatch into a later, higher paint layer so its
      // ring is no longer covered; `position: relative` is what makes `zIndex` apply here at
      // all for a *general* in-flow, non-positioned element — without it `z-index` is ignored
      // per spec. (A `swatch` specifically is also a direct flex item of `swatches`, and the
      // Flexbox spec carves out flex items as one exception where `z-index` alone establishes
      // a stacking context even while `position` stays `static` — confirmed empirically here
      // too, `z-index` alone did already fix this swatch's own outline. `position: relative` is
      // kept anyway: it costs nothing — no `top`/`left`/etc. offset is set, so it does not move
      // the box — and it keeps this rule correct even if `swatch` is ever composed inside a
      // non-flex parent, rather than depending on a layout detail owned by a sibling file.)
      // Neither property is set outside `_focusVisible`, so normal (unfocused) stacking is
      // completely unaffected.
      _focusVisible: {
        position: 'relative',
        zIndex: 1,
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
    },
  }),
};

